import pandas as pd, re

def extract_annual(path,sheet,col):
    df=pd.read_excel(path,sheet_name=sheet,header=None)
    vals={}
    cur=None
    q2024=[]
    for _,row in df.iterrows():
        label=row[0]
        if not isinstance(label,str):
            continue
        s=label.strip()
        m=re.match(r'^(\d{4}):?\s*I\.', s)
        if m:
            cur=int(m.group(1))
            if cur==2024:
                q2024.append(float(row[col]))
            else:
                vals[cur]=float(row[col])
            continue
        if cur==2024 and re.match(r'^(II\.|III\.|IV\.|II p\.|III p\.|IV p\.)', s):
            q2024.append(float(row[col]))
    if q2024:
        vals[2024]=sum(q2024)/len(q2024)
    return pd.Series(vals).sort_index()
for f,s in [('/root/ERP-2025-table10.xls','B10'),('/root/ERP-2025-table12.xls','B12')]:
    ser=extract_annual(f,s,1)
    print(f, ser.index.min(), ser.index.max(), len(ser), ser.index.tolist()[:5], ser.index.tolist()[-5:])
    print('missing', set(range(1973,2025))-set(ser.index))
